const msg = $input.first().json.message || {};

// Hard allowlist: only the authorized admin chat can confirm/reject
// payments or resolve escalations.
const AUTHORIZED_ADMIN_CHAT_IDS = ['8778390981'];
if (!AUTHORIZED_ADMIN_CHAT_IDS.includes(String(msg.chat?.id))) return [];

// Only process replies to messages
if (!msg.reply_to_message) return [];

const adminText   = (msg.text || '').trim();
const adminChatId = msg.chat?.id;
const replyToText = msg.reply_to_message?.text || '';

// --- Payment verification reply? ---
if (/Registration ID:/i.test(replyToText)) {
  const regMatch = replyToText.match(/Registration ID:\*?\s*([a-f0-9-]{36})/i);
  if (!regMatch) return [];

  let verdict = null;
  if (/^confirmed$/i.test(adminText)) verdict = 'CONFIRMED';
  else if (/^not confirmed$/i.test(adminText)) verdict = 'NOT_CONFIRMED';
  if (!verdict) return []; // admin must reply exactly CONFIRMED or NOT CONFIRMED

  return [{ json: {
    flow_type: 'payment_verification',
    registration_id: regMatch[1],
    verdict,
    admin_chat_id: adminChatId
  } }];
}

// --- Escalation (complaint) reply ---
if (/Escalation ID:/i.test(replyToText)) {
  const escalationMatch = replyToText.match(/Escalation ID:\*?\s*([a-f0-9-]{36})/i);
  if (!escalationMatch) return [];

  const waMatch = replyToText.match(/WA:\*?\s*(\d+)/i);
  if (!waMatch) return [];

  const codeMatch = replyToText.match(/Code:\*?\s*(DTP-\d+)/i);

  return [{ json: {
    flow_type: 'escalation',
    escalation_id: escalationMatch[1],
    admin_reply: adminText,
    wa_number: waMatch[1],
    customer_code: codeMatch ? codeMatch[1] : '',
    admin_chat_id: adminChatId
  } }];
}

return [];

const msgStats    = $('Get Message Stats').first().json;
const newCusts    = $('Get New Customers').first().json;
const totalCusts  = $('Get Total Customers').first().json;
const custSplits  = $('Get Customer Splits').first().json;
const promoStats  = $('Get Promo Stats').first().json;
const slabBreakdownRows = $('Get Slab Breakdown Today').all().map(i => i.json);
const slabsPickedLine = slabBreakdownRows.length > 0
  ? slabBreakdownRows.map(r => `${r.slab}: ${r.quantity}`).join(' | ')
  : 'none yet';

const productsByLocationEarly = $('Get Daily Products By Location').all().map(i => i.json);
const cartonsByLocation = {};
for (const row of productsByLocationEarly) {
  if (!row.slab) continue;
  cartonsByLocation[row.location] = (cartonsByLocation[row.location] || 0) + parseInt(row.orders || 0);
}
const locationCartonsLine = Object.entries(cartonsByLocation)
  .map(([loc, qty]) => `${loc}: ${qty}`)
  .join(', ');

const today = new Date().toLocaleDateString('en-GB', {
  timeZone: 'Africa/Lagos',
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const amountGenerated = parseFloat(promoStats.amount_generated || 0);
const amountConfirmed = parseFloat(promoStats.amount_confirmed || 0);
const redemptionRate = amountGenerated > 0
  ? Math.round((amountConfirmed / amountGenerated) * 100)
  : 0;

function scaleGiftText(giftText, qty) {
  const m = (giftText || '').match(/^(\d+)\s*(.+)$/);
  if (!m) return giftText || '';
  const totalQty = parseInt(m[1]) * qty;
  return `${totalQty} ${m[2]}`;
}

function formatActivityDate(iso) {
  if (!iso) return '';
  return new Date(iso).toLocaleDateString('en-GB', {
    timeZone: 'Africa/Lagos',
    day: 'numeric',
    month: 'short',
    year: 'numeric'
  });
}

// Gift breakdown by product -- slabs sharing the same gift text get combined.
const DIVIDER = '\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500';

const report = [
  `\ud83d\udcca <b>Favour Daily Report</b>`,
  `\ud83d\udcc5 ${today}`,
  ``,
  DIVIDER,
  `\ud83c\udff7\ufe0f <b>DTP REPORT</b>`,
  DIVIDER,
