// ------------------------------------------------------------------
// Build the CSV file content, matching the reference dashboard layout:
// Promo Performance summary, Top Products Taken, Recent Promo Activities.
// ------------------------------------------------------------------
function csvEscape(val) {
  const s = String(val === null || val === undefined ? '' : val);
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function csvRow(arr) {
  return arr.map(csvEscape).join(',');
}

