const toDate   = query.to   || now.toISOString().split('T')[0];

// Always append time — from table_17 at midnight, to ends at end of day
const from = `${fromDate}T00:00:00`;
const to   = `${toDate}T23:59:59`;

return [{ json: { from, to } }];

const items = $input.all();

const totalEngaged = items.find(i => i.json.total_engaged !== undefined)?.json.total_engaged || 0;
const newJoiners = items.find(i => i.json.new_joiners !== undefined)?.json.new_joiners || 0;
