  }));

function scaleGiftText(giftText, qty) {
  const m = (giftText || '').match(/^(\d+)\s*(.+)$/);
  if (!m) return giftText || null;
  const totalQty = parseInt(m[1]) * qty;
  return `${totalQty} ${m[2]}`;
}

const recentActivity = items
  .filter(i => i.json.row_type === 'activity')
  .map(i => ({
    customer_name: i.json.customer_name,
    code: i.json.code,
    location: i.json.location,
