const amountGenerated = parseFloat(agg.amount_generated || 0);
const amountConfirmed = parseFloat(agg.amount_confirmed || 0);
const redemptionRate = amountGenerated > 0
  ? Math.round((amountConfirmed / amountGenerated) * 100)
  : 0;

const dates = $('Extract Dates').item.json;

return [{
