return [{ json: { wants_promo: wantsPromo } }];

const customerData = $('Merge Customer Data').first().json;
const reg = $('Create Registration').first().json;

const cycle = $('Get Active Promo Cycle').first().json;
const reply = `Great! Let's get you registered for the ${cycle.name} \ud83c\udf89\n\nFirst \u2014 do you already have a WARPSPEED account? (Yes/No)`;

return [{ json: {
  registration_id: reg.id,
