const reg = $('Get Registration State').first().json;
const customerData = $('Merge Customer Data').first().json;
const waMsg = $('Parse WA Message').first().json;
const text = (customerData.text || '').trim();
const lower = text.toLowerCase();

let newStatus = reg.status;
let has_warpspeed = null, pickup_location = null, heard_via = null,
    receipt_message_id = null, participation_code = null, promoCycleId = null;
let fullName = reg.full_name || null;
let slabSummary = reg.slab || null;
let amount_due = (reg.amount_due !== undefined && reg.amount_due !== null) ? reg.amount_due : null;
let itemsToSave = null;
let reply = '';
let notifyAdmin = false;

const currentItems = Array.isArray(reg.items) ? reg.items : [];

// The cycle this registration is actually tied to (once set) always
// wins over "whatever's active right now" -- keeps pricing stable for
// an in-flight registration even if a new cycle starts concurrently.
// For turns before a cycle is attached (still at the menu), fall back
// to whichever cycle is currently active.
const activeCycleItem = $('Get Active Promo Cycle').first();
const activeCycle = (activeCycleItem && activeCycleItem.json && activeCycleItem.json.id) ? activeCycleItem.json : null;
const cycle = reg.cycle || activeCycle || null;

function buildPrices(cycleObj) {
  const map = {};
  if (!cycleObj || !Array.isArray(cycleObj.slabs)) return map;
  for (const s of cycleObj.slabs) {
    map[s.slab] = { product: s.product, gift: s.gift, prices: s.prices || {} };
  }
  return map;
}
const PRICES = buildPrices(cycle);
const CYCLE_LOCATIONS = (cycle && Array.isArray(cycle.locations)) ? cycle.locations : [];

// Case-insensitive match against this cycle's actual location list --
// returns the canonically-cased location name, or null if no match.
function matchLocation(inputText) {
  const lowerInput = inputText.toLowerCase();
  for (const loc of CYCLE_LOCATIONS) {
    if (lowerInput.includes(loc.toLowerCase())) return loc;
  }
  return null;
}

function paymentInstructionsBlock() {
  const psItem = $('Get Payment Settings').first();
  const ps = psItem ? psItem.json : null;
  const accountName = (ps && ps.account_name) ? ps.account_name : '[TO BE PROVIDED]';
  const accountNumber = (ps && ps.account_number) ? ps.account_number : '[TO BE PROVIDED]';
  const bankName = (ps && ps.bank_name) ? ps.bank_name : '[TO BE PROVIDED]';
  return 'Please pay into:\n' +
    `Account Name: ${accountName}\n` +
    `Account Number: ${accountNumber}\n` +
    `Bank Name: ${bankName}\n`;
}

const WARPSPEED_CONTACTS =
  'Amara \u2014 [PHONE]\n' +
  'Sign up here: [URL]';

function parseSlabItems(msgText) {
  const numberWords = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, a: 1, an: 1, couple: 2, few: 3 };

  // Match a single word against the current cycle's actual product names --
  // exact word match, or a prefix match either direction (so "reg" matches
  // "Reg" in "Delta Reg 60g", and "regular" matches it too via the reverse
  // prefix check). Fully derived from table_22, which is itself built from
  // whatever slabs this cycle actually has -- no hardcoded product names,
  // works the same whether there's 1 slab or 10.
  function matchProductWord(word) {
    const w = word.toLowerCase();
    if (w.length < 2) return null;
    for (const [letter, p] of Object.entries(PRICES)) {
      const productWords = (p.product || '').toLowerCase().split(/[\s,()]+/).filter(Boolean);
      for (const pw of productWords) {
        if (pw.length < 2) continue;
        if (pw === w) return letter;
        if (pw.length >= 3 && w.length >= 3 && (pw.startsWith(w) || w.startsWith(pw))) return letter;
      }
    }
    return null;
  }

  const validLetters = Object.keys(PRICES);
  const segLower = msgText.toLowerCase();

  const filler = /\b(i want|i'll take|i will take|lets do|let's do|go with|option|please|i choose|choose|i'll go with)\b/g;
  const cleanedForBare = segLower.replace(filler, '').trim().replace(/[^a-z]/g, '');
  if (cleanedForBare.length === 1 && validLetters.includes(cleanedForBare.toUpperCase())) {
    return [{ slab: cleanedForBare.toUpperCase(), quantity: 1 }];
  }

  const segments = segLower.split(/,|\n|;|\band\b|\+|\bplus\b/).map(s => s.trim()).filter(Boolean);
  const found = {};
  for (const seg of segments) {
    let slab = null;
    const slabMatch = seg.match(/slab[\s-]?([a-j])\b/);
    if (slabMatch && validLetters.includes(slabMatch[1].toUpperCase())) {
      slab = slabMatch[1].toUpperCase();
    } else {
      const words = seg.split(/[^a-z0-9]+/).filter(Boolean);
      for (const w of words) {
        const m = matchProductWord(w);
        if (m) { slab = m; break; }
      }
    }
    if (!slab) continue;
    let qty = 1;
    const digitMatch = seg.match(/(\d+)/);
    if (digitMatch) {
      qty = parseInt(digitMatch[1]);
    } else {
      for (const [word, val] of Object.entries(numberWords)) {
        if (new RegExp(`\\b${word}\\b`).test(seg)) { qty = val; break; }
      }
    }
    found[slab] = (found[slab] || 0) + qty;
  }
  return Object.entries(found).map(([slab, quantity]) => ({ slab, quantity }));
}

function priceItems(items, pickupLocation) {
  const priced = items.map(it => {
    const priceMap = PRICES[it.slab] ? PRICES[it.slab].prices : {};
    const unit = priceMap[pickupLocation] || 0;
    return { slab: it.slab, quantity: it.quantity, unit_price: unit, line_total: unit * it.quantity };
  });
  const total = priced.reduce((s, it) => s + it.line_total, 0);
  return { priced, total };
}

// Scale a gift description like "18 bars of Delta Guest 20g" by the
// cart quantity, so 3 cartons correctly shows "54 bars of..." instead
// of a confusing "3 \u00d7 18 bars of...".
function scaleGiftText(giftText, qty) {
  const m = (giftText || '').match(/^(\d+)\s*(.+)$/);
  if (!m) return giftText;
  const base = parseInt(m[1]);
  const totalQty = base * qty;
  const breakdown = qty > 1 ? ` (${base} \u00d7 ${qty})` : '';
  return `${totalQty} ${m[2]}${breakdown}`;
}

function summarizeItems(priced) {
  return priced.map(it => {
    const p = PRICES[it.slab];
    const giftLine = scaleGiftText(p.gift, it.quantity);
    return `${it.quantity} \u00d7 Slab ${it.slab} (${p.product}) \u2014 \u20a6${it.line_total.toLocaleString()} \u2192 ${giftLine}`;
  }).join('\n');
}

function slabListLine(items) {
  return items.map(it => `${it.quantity} \u00d7 Slab ${it.slab} (${PRICES[it.slab].product})`).join('\n');
}

function summaryString(items) {
  return items.map(it => `${it.slab}x${it.quantity}`).join(',');
}

function slabMenuText() {
  const letters = Object.keys(PRICES).sort();
  return letters.map(l => `*${l}* \u2014 ${PRICES[l].product} \u2192 Get ${PRICES[l].gift} (per carton)`).join('\n');
}

const modificationStatuses = ['awaiting_pickup', 'awaiting_source', 'awaiting_receipt', 'awaiting_verification'];
const additiveRegex = /\b(also want|also need|i also|add|include|as well|forgot to add|forgot to include|don't forget|dont forget)\b/i;
const replaceRegex = /\b(instead|change to|rather than|rather have|modify|update table_23|make it|correction)\b/i;
const pronounQtyRegex = /(\d+|one|two|three|four|five|six|seven|eight|nine|ten)\s*(of\s+)?(that|this|the)\s*(slab|one|carton)/i;

const inModStatus = currentItems.length > 0 && modificationStatuses.includes(reg.status);
const isAdditive = inModStatus && additiveRegex.test(lower);
const isReplace = inModStatus && !isAdditive && (replaceRegex.test(lower) || pronounQtyRegex.test(lower));
const looksLikeModification = isAdditive || isReplace;

if (looksLikeModification) {
  let parsedItems = parseSlabItems(text);

  if (isReplace && parsedItems.length === 0) {
    const m = lower.match(pronounQtyRegex);
    if (m && currentItems.length === 1) {
      const numberWords = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
      const qtyRaw = m[1];
      const qty = /^\d+$/.test(qtyRaw) ? parseInt(qtyRaw) : numberWords[qtyRaw];
      parsedItems = [{ slab: currentItems[0].slab, quantity: qty }];
    }
  }

  let finalItems = null;
  if (parsedItems.length > 0) {
    if (isAdditive) {
      const merged = {};
      for (const it of currentItems) merged[it.slab] = (merged[it.slab] || 0) + it.quantity;
      for (const it of parsedItems) merged[it.slab] = (merged[it.slab] || 0) + it.quantity;
      finalItems = Object.entries(merged).map(([slab, quantity]) => ({ slab, quantity }));
    } else {
      finalItems = parsedItems;
    }
  }

  if (finalItems) {
    if (reg.pickup_location) {
      const { priced, total } = priceItems(finalItems, reg.pickup_location);
      itemsToSave = priced;
      amount_due = total;
      slabSummary = summaryString(priced);
      newStatus = 'awaiting_receipt';
      reply = `${isAdditive ? 'Added! Here\u2019s your updated order' : 'No problem, updated your order'}:\n\n${summarizeItems(priced)}\n\n` +
        `Your new total is *\u20a6${total.toLocaleString()}*.\n\n` +
        paymentInstructionsBlock() +
        `Amount: \u20a6${total.toLocaleString()}\n\n` +
        'Once payment has been made, kindly send your payment receipt or proof of payment here for verification.';
    } else {
      itemsToSave = finalItems.map(it => ({ slab: it.slab, quantity: it.quantity, unit_price: null, line_total: null }));
      slabSummary = summaryString(finalItems);
      newStatus = 'awaiting_pickup';
      reply = `Got it, updated to:\n${slabListLine(finalItems)}\n\nWhich pickup location is closest to you \u2014 ${CYCLE_LOCATIONS.join(', ')}?`;
    }
  } else {
    reply = 'Which slab would you like to update, and to how many cartons?';
  }
} else {

switch (reg.status) {
  case 'awaiting_menu_choice': {
    if (/(^|\s)1(\s|$)/.test(lower) || lower.includes('code') || lower.includes('promo code')) {
      newStatus = 'menu_general';
      reply = `Hi, I'm Favour, your Orange Group Digital Promoter \ud83d\ude0a\nYour promo code is ${customerData.customer_code}.\nKindly show this code to our promoter to collect your gift.`;
    } else if (/(^|\s)2(\s|$)/.test(lower) || lower.includes('promo') || lower.includes('participate') || lower.includes('join')) {
      if (!activeCycle) {
        const upcomingItem = $('Get Next Upcoming Cycle').first();
        const upcoming = (upcomingItem && upcomingItem.json && upcomingItem.json.id) ? upcomingItem.json : null;
        if (upcoming) {
          reply = 'There\u2019s no ongoing MaketNG promo right now, but a new one is being set up \u2014 check back soon! In the meantime, would you like your DTP promo code? Reply *1*.';
        } else {
          reply = 'There\u2019s no ongoing MaketNG promo right now \u2014 please check back soon! In the meantime, would you like your DTP promo code? Reply *1*.';
        }
      } else {
        newStatus = 'awaiting_warpspeed';
        promoCycleId = activeCycle.id;
        reply = `Great! Let's get you registered for the ${activeCycle.name} \ud83c\udf89\n\nFirst \u2014 do you already have a WARPSPEED account? (Yes/No)`;
      }
    } else {
      reply = 'Sorry, I didn\'t catch that. Please reply with *1* for your DTP Code, or *2* to take part in the MaketNG promo.';
    }
    break;
  }
  case 'awaiting_warpspeed': {
    if (/\b(yes|yeah|yep|yup|i do|have one|i have)\b/.test(lower)) {
      has_warpspeed = true;
      newStatus = 'awaiting_full_name';
      reply = `Perfect \u2705\n\nWhat's your full name \u2014 first and last name? (for our gift collection record)`;
    } else if (/\b(no|nope|don'?t|do not|dont)\b/.test(lower)) {
      has_warpspeed = false;
