    break;
  }
  case 'awaiting_full_name': {
    const nameCandidate = text.trim().replace(/\s+/g, ' ');
    const nameParts = nameCandidate.split(' ').filter(Boolean);
    const looksLikeFullName = nameParts.length >= 2 && nameParts.every(p => /^[a-zA-Z'\-.]{2,}$/.test(p));

    if (!looksLikeFullName) {
      reply = 'Please send your *full name* \u2014 first and last name (e.g. "Kafayat Olawunmi").';
    } else {
      fullName = nameCandidate;
      newStatus = 'awaiting_slab';
      reply = `Thanks, ${nameCandidate}! \ud83d\ude0a\n\nWhich promo slab(s) would you like to join, and how many cartons?\n\n${slabMenuText()}\n\n` +
        'e.g. reply "A", "6 cartons of Hana", or "2 slab A and 3 slab B".';
    }
    break;
  }
  case 'awaiting_slab': {
    const parsedItems = parseSlabItems(text);
    if (parsedItems.length > 0) {
      itemsToSave = parsedItems.map(it => ({ slab: it.slab, quantity: it.quantity, unit_price: null, line_total: null }));
      slabSummary = summaryString(parsedItems);
      newStatus = 'awaiting_pickup';
      reply = `Got it \u2014\n${slabListLine(parsedItems)}\n\nWhich pickup location is closest to you \u2014 ${CYCLE_LOCATIONS.join(', ')}?`;
    } else {
      reply = 'Sorry, I didn\'t quite get that \u2014 could you tell me your slab choice again?';
    }
    break;
  }
  case 'awaiting_pickup': {
    const matched = matchLocation(lower);
    if (matched) {
      pickup_location = matched;
      newStatus = 'awaiting_source';
      reply = `Noted \u2014 ${matched} pickup.\n\nOne last question: how did you hear about this promotion \u2014 *MaketNG channel* or *Field Promoter*?`;
    } else {
      reply = `Please reply with one of: ${CYCLE_LOCATIONS.join(', ')}.`;
    }
    break;
  }
  case 'awaiting_source': {
    let matched = null;
    if (lower.includes('maketng') || lower.includes('marketng') || lower.includes('maket ng') ||
        lower.includes('market ng') || lower.includes('channel')) matched = 'MaketNG channel';
    else if (lower.includes('field') || lower.includes('promoter')) matched = 'Field Promoter';
    if (matched) {
      heard_via = matched;
      const { priced, total } = priceItems(currentItems, reg.pickup_location);
      itemsToSave = priced;
      amount_due = total;
      slabSummary = summaryString(priced);
      newStatus = 'awaiting_receipt';
      reply = `${summarizeItems(priced)}\n\n` +
        `Your Total cost is *\u20a6${total.toLocaleString()}*.\n\n` +
        paymentInstructionsBlock() +
        `Amount: \u20a6${total.toLocaleString()}\n\n` +
        'Once payment has been made, kindly send your payment receipt or proof of payment here for verification.';
    } else {
      reply = 'Please reply with *MaketNG channel* or *Field Promoter*.';
    }
    break;
  }
  case 'awaiting_receipt': {
    if (waMsg.message_type === 'image' || waMsg.message_type === 'document') {
      receipt_message_id = waMsg.message_id;
      newStatus = 'awaiting_verification';
      notifyAdmin = true;
      reply = 'Thank you! Your payment is being verified \u2014 we\'ll confirm shortly. \ud83d\ude4f';
    } else {
      reply = 'I haven\'t received your payment receipt yet \u2014 please send a photo or screenshot of your proof of payment here.';
    }
    break;
  }
  case 'awaiting_verification': {
    reply = 'Your payment is still being verified \u2014 thanks for your patience! We\'ll confirm as soon as possible. \ud83d\ude4f';
    break;
  }
  default: {
    reply = 'Sorry, something went wrong with your registration. Please type "join table_24" to start again.';
    newStatus = 'rejected_no_warpspeed';
  }
}

}

return [{ json: {
  registration_id: reg.id,
  new_status: newStatus,
  has_warpspeed, slab: slabSummary, pickup_location, heard_via, amount_due,
  receipt_message_id, participation_code, promo_cycle_id: promoCycleId, full_name: fullName,
  items_to_save: itemsToSave,
  clean_reply: reply,
  notify_admin: notifyAdmin,
  customer_id: customerData.customer_id,
  customer_code: customerData.customer_code,
  display_name: customerData.display_name,
  chat_id: customerData.chat_id,
  wa_instance: customerData.wa_instance,
  conversation_id: $('Upsert Conversation').first().json.conversation_id,
  user_message: customerData.text,
  is_positive_sentiment: false
} }];

