const reg = $('Fetch Registration').first().json;
const confirmed = $('Confirm Registration & Generate Code').first().json;

function scaleGiftText(giftText, qty) {
  const m = (giftText || '').match(/^(\d+)\s*(.+)$/);
  if (!m) return giftText;
  const base = parseInt(m[1]);
  const totalQty = base * qty;
  const breakdown = qty > 1 ? ` (${base} \u00d7 ${qty})` : '';
  return `${totalQty} ${m[2]}${breakdown}`;
}

const cycleSlabs = (reg.cycle && Array.isArray(reg.cycle.slabs)) ? reg.cycle.slabs : [];
const PRODUCT_NAMES = { A: 'Hana Hair Cream', B: 'Delta Reg 60g', C: 'Gardia Mosquito Repellent Cream' };
const items = Array.isArray(reg.items) ? reg.items : [];
const itemsSummary = items
  .map(it => {
    const slabInfo = cycleSlabs.find(s => s.slab === it.slab);
    const productName = (slabInfo && slabInfo.product) || PRODUCT_NAMES[it.slab] || it.slab;
    const giftLine = slabInfo ? ` \u2192 ${scaleGiftText(slabInfo.gift, it.quantity)}` : '';
    return `${it.quantity} \u00d7 Slab ${it.slab} (${productName})${giftLine}`;
  })
  .join('\n');

const reply = 'Your payment has been confirmed. \u2705\n\n' +
  (itemsSummary ? `Your order:\n${itemsSummary}\n\n` : '') +
  (reg.cycle && reg.cycle.collection_date
    ? `Please ensure to get your order and redeem your gift on *${new Date(reg.cycle.collection_date).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}* in your location.\n\n`
    : '') +
  `Your participation code is *${confirmed.participation_code}*. Please show this at pickup.`;

return [{ json: {
  wa_id: reg.wa_id,
  customer_code: reg.customer_code,
  full_name: reg.full_name || reg.display_name,
  participation_code: confirmed.participation_code,
  conversation_id: confirmed.conversation_id,
  customer_id: confirmed.customer_id,
  clean_reply: reply
} }];

const reg = $('Fetch Registration').first().json;
const rejected = $('Reject Registration Payment').first().json;

const reply = 'We are unable to confirm your payment at the moment.\n\n' +
  'Kindly allow some time or send your payment receipt again to retry verification.';

return [{ json: {
  wa_id: reg.wa_id,
  customer_code: reg.customer_code,
  full_name: reg.full_name || reg.display_name,
  participation_code: null,
  conversation_id: rejected.conversation_id,
  customer_id: rejected.customer_id,
  clean_reply: reply
} }];

const customerData = $('Merge Customer Data').first().json;
const reg = $('Create Menu Record').first().json;

const greeting = customerData.is_new
  ? `Hi, I'm Favour, your Orange Group Digital Promoter \ud83d\ude0a\n\n`
  : `Hey again! \ud83d\ude0a\n\n`;

const activeCycleItem = $('Get Active Promo Cycle').first();
const activeCycle = (activeCycleItem && activeCycleItem.json && activeCycleItem.json.id) ? activeCycleItem.json : null;
const option2 = activeCycle ? `Take part in the ${activeCycle.name}` : `Ask about our next promo`;

const reply = `${greeting}How can I help you today?\n\n*1* \u2014 Get my DTP Code\n*2* \u2014 ${option2}\n\nReply with 1 or 2.`;

return [{ json: {
  registration_id: reg.id,
  new_status: reg.status,
  has_warpspeed: null, slab: null, pickup_location: null, heard_via: null,
  amount_due: null, receipt_message_id: null, participation_code: null,
  clean_reply: reply,
  notify_admin: false,
  customer_id: customerData.customer_id,
  customer_code: customerData.customer_code,
  display_name: customerData.display_name,
  chat_id: customerData.chat_id,
  wa_instance: customerData.wa_instance,
  conversation_id: $('Upsert Conversation').first().json.conversation_id,
  user_message: customerData.text,
  is_positive_sentiment: false
} }];

const text = ($('Merge Customer Data').first().json.text || '').trim().toLowerCase();
const clean = text.replace(/[!.,?]+$/g, '').trim();

const greetingPattern = /^(hi+|hello+|hey+|hiya|yo|sup|good\s?morning|good\s?afternoon|good\s?evening|morning|afternoon|evening|howdy|hi\s?there|hello\s?there)$/i;

return [{ json: { is_bare_greeting: greetingPattern.test(clean) } }];

// Update table_25's RETURNING * only carries DB columns (no clean_reply,
// chat_id, etc.), so recover the real payload from table_30 code node
// actually produced it in this branch.
let src;
for (const name of ['Continue Registration', 'Start Registration', 'Ask Menu Choice', 'No Active Promo Reply']) {
  try {
    const j = $(name).first().json;
    if (j && j.clean_reply !== undefined) { src = j; break; }
  } catch (e) { /* this node didn't run in this branch */ }
}
if (!src) src = {};
return [{ json: src }];

let src;
for (const name of ['Build Confirmation Message', 'Build Rejection Message']) {
  try {
    const j = $(name).first().json;
    if (j && j.clean_reply !== undefined) { src = j; break; }
  } catch (e) {}
}
if (!src) src = {};
return [{ json: src }];

const customerData = $('Merge Customer Data').first().json;

const upcomingItem = $('Get Next Upcoming Cycle').first();
const upcoming = (upcomingItem && upcomingItem.json && upcomingItem.json.id) ? upcomingItem.json : null;

let reply;
if (upcoming) {
  reply = 'There\u2019s no ongoing MaketNG promo right now, but a new one is being set up \u2014 check back soon! In the meantime, just say hi for your DTP promo code.';
} else {
  reply = 'There\u2019s no ongoing MaketNG promo right now \u2014 please check back soon! ' +
    'In the meantime, would you like your DTP promo code? Reply *1* or just say hi again.';
}

return [{ json: {
  registration_id: null, new_status: null,
  has_warpspeed: null, slab: null, pickup_location: null, heard_via: null,
  amount_due: null, receipt_message_id: null, participation_code: null, promo_cycle_id: null,
  clean_reply: reply,
  notify_admin: false,
  customer_id: customerData.customer_id,
  customer_code: customerData.customer_code,
  display_name: customerData.display_name,
  chat_id: customerData.chat_id,
  wa_instance: customerData.wa_instance,
  conversation_id: $('Upsert Conversation').first().json.conversation_id,
  user_message: customerData.text,
  is_positive_sentiment: false
} }];

const msg = $('Telegram Trigger').first().json.message || {};
const text = (msg.text || '').trim();

// Hard allowlist: only the authorized admin chat can trigger any of
// this. Anything else is ignored outright, before any other logic
// runs -- this gates /newpromo, /editpromo, and /setpayment, since
// /setpayment in particular controls where customer money gets sent.
const AUTHORIZED_ADMIN_CHAT_IDS = ['8778390981'];
if (!AUTHORIZED_ADMIN_CHAT_IDS.includes(String(msg.chat?.id))) {
  return [{ json: { route: 'ignore', chat_id: msg.chat?.id, text, payment_details: null } }];
}

const sessionItem = $('Get Admin Session').first();
const session = sessionItem ? sessionItem.json : null;
const hasSession = !!(session && session.id);
const hasPhoto = Array.isArray(msg.photo) && msg.photo.length > 0;

const authItem = $('Get Auth Settings').first();
const authSettings = authItem ? authItem.json : null;
const hasPassword = !!(authSettings && authSettings.password_hash);

let route = 'ignore';
let paymentDetails = null;

const setPaymentMatch = text.match(/^\/setpayment\s+(.+)$/is);

if (/^\/help$/i.test(text)) {
  route = 'help';
} else if (/^\/status$/i.test(text)) {
  route = 'status';
} else if (hasSession && session.status === 'awaiting_slab_count' && hasPhoto) {
  // Flyer photo dropped at the very first slab prompt -- parsed
  // separately and can fill however many slabs it contains (up to 10).
  route = 'continue_wizard_photo';
} else if (hasSession && session.status === '[ID]') {
  // Mid-bootstrap: their next message is the password they're choosing,
  // not a new command -- route here regardless of what it looks like.
  route = 'continue_payment_setup';
} else if (!hasSession && /^\/newpromo$/i.test(text)) {
  route = 'start_wizard';
} else if (!hasSession && /^\/editpromo$/i.test(text)) {
  route = 'start_edit';
} else if (!hasSession && /^\/startpromo$/i.test(text)) {
  route = 'start_promo';
} else if (!hasSession && /^\/stoppromo$/i.test(text)) {
  route = 'stop_promo';
} else if (!hasSession && setPaymentMatch) {
  const parts = setPaymentMatch[1].split(',').map(s => s.trim());
  if (parts.length === 3 && parts.every(p => p.length > 0)) {
    paymentDetails = { account_name: parts[0], account_number: parts[1], bank_name: parts[2] };
    route = hasPassword ? 'set_payment_request' : 'set_payment_bootstrap';
  } else {
    route = 'set_payment_error';
  }
} else if (hasSession) {
  route = 'continue_wizard';
}

return [{ json: { route, chat_id: msg.chat?.id, text, payment_details: paymentDetails } }];

const session = $('Get Admin Session').first().json;
const msg = $('Telegram Trigger').first().json.message || {};
const text = (msg.text || '').trim();
const chatId = msg.chat?.id;

let draft = session.draft || {};
let newStatus = session.status;
let reply = '';
let pendingEdit = null;

const MAX_SLABS = 10;

function fmt(d) {
  if (!d) return 'not set yet';
  return new Date(d).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
}

function splitList(raw) {
  return raw.split(/[,\n;]+/).map(s => s.trim()).filter(Boolean);
}

function parsePrices(raw, locations) {
  const vals = splitList(raw).map(v => parseFloat(v.replace(/[^\d.]/g, '')));
  if (vals.some(v => isNaN(v))) return null;
  if (vals.length === 1) {
    return Object.fromEntries(locations.map(loc => [loc, vals[0]]));
  }
  if (vals.length === locations.length) {
    return Object.fromEntries(locations.map((loc, i) => [loc, vals[i]]));
  }
  return null;
}

function pricesLine(prices) {
  return Object.entries(prices).map(([loc, p]) => `${loc}: \u20a6${p.toLocaleString()}`).join(', ');
}

function slabSummaryText(slabs) {
  return slabs
    .slice()
    .sort((a, b) => a.slab.localeCompare(b.slab))
    .map(s => `${s.slab}: ${s.product} \u2192 ${s.gift}\n   ${pricesLine(s.prices)}`)
    .join('\n');
}

function buildConfirmReply(d) {
  const summary = slabSummaryText(d.slabs || []);
  return `Here's the full promo cycle \u2014 please check carefully:\n\n` +
    `*${d.name}*\n` +
    `Collection: ${fmt(d.collection_date)}\n` +
    `Locations: ${(d.locations || []).join(', ')}\n\n${summary}\n\n` +
    `Reply *CONFIRM* to save this \u2014 it won't go live until you send /startpromo, or *CANCEL* to discard.`;
}

switch (session.status) {
  // ----------------------------------------------------------------
  // 0. How many slabs? (1-10). A photo is handled upstream instead
  //    of a number -- the flyer's own contents determine the count.
  // ----------------------------------------------------------------
  case 'awaiting_slab_count': {
    const n = parseInt(text.trim());
    if (!Number.isInteger(n) || n < 1 || n > MAX_SLABS) {
      reply = `Please reply with a number from 1 to ${MAX_SLABS} \u2014 how many products/slabs will this promo have? ` +
        'Or send a photo of the flyer instead and I\'ll work out the count from table_34';
    } else {
      draft.slab_count = n;
      draft.slab_index = 0;
      draft.slabs = [];
      newStatus = 'awaiting_slab_entry';
      reply = `Got it \u2014 ${n} slab${n > 1 ? 's' : ''}.\n\n` +
        `Slab A \u2014 send: product, gift\ne.g. "Hana Hair Cream, 18 bars of Delta Guest 20g"`;
    }
    break;
  }

  // ----------------------------------------------------------------
  // 1. Slabs (product + gift only -- no pricing yet, that comes
  //    after locations are known). Loops however many times the
  //    admin said, one slab per message.
  // ----------------------------------------------------------------
  case 'awaiting_slab_entry': {
    const idx = draft.slab_index || 0;
    const letter = String.fromCharCode(65 + idx);
    const parts = text.split(',').map(s => s.trim());
    if (parts.length !== 2) {
      reply = `Please send exactly 2 values separated by a comma: product, gift.\ne.g. "Hana Hair Cream, 18 bars of Delta Guest 20g"`;
    } else {
      const [product, gift] = parts;
      draft.slabs = (draft.slabs || []).filter(s => s.slab !== letter);
      draft.slabs.push({ slab: letter, product, gift, prices: {} });
      draft.slab_index = idx + 1;
      if (draft.slab_index < draft.slab_count) {
        const nextLetter = String.fromCharCode(65 + draft.slab_index);
        newStatus = 'awaiting_slab_entry';
        reply = `Slab ${letter} saved \u2014 ${product}.\n\nNow Slab ${nextLetter} \u2014 send: product, gift`;
      } else {
        newStatus = 'awaiting_locations';
        reply = `Slab ${letter} saved \u2014 ${product}.\n\nAll ${draft.slab_count} slabs are in. Now, which pickup locations will this promo be available at? Send them all in one message -- commas or new lines, either works.\ne.g. "Mushin, Ikotun, Yaba"`;
      }
    }
    break;
  }

  // ----------------------------------------------------------------
  // Review/correct the flyer-derived slabs before moving on -- a
  // vision model can misread a flyer, so give a chance to fix it
  // here rather than only catching it at the very final review.
  // ----------------------------------------------------------------
  case 'awaiting_flyer_confirm': {
    if (/^confirm$/i.test(text)) {
      newStatus = 'awaiting_locations';
      reply = 'Now, which pickup locations will this promo be available at? Send them all in one message \u2014 commas or new lines, either works.\n' +
        'e.g. "Mushin, Ikotun, Yaba"';
    } else {
      const m = text.match(/^slab\s*([a-j])\s*:\s*(.+)$/i);
      if (!m) {
        reply = 'Reply *CONFIRM* if the slabs look right, or fix one like: "slab a: correct product, correct gift".';
      } else {
        const letter = m[1].toUpperCase();
        const parts = m[2].split(',').map(s => s.trim());
        if (parts.length !== 2) {
          reply = `Send Slab ${letter} as "slab ${letter.toLowerCase()}: product, gift".`;
        } else {
          const [product, gift] = parts;
          const slabObj = (draft.slabs || []).find(s => s.slab === letter);
          if (slabObj) {
            slabObj.product = product;
            slabObj.gift = gift;
          } else {
            reply = `Slab ${letter} wasn't part of what the flyer showed \u2014 only correcting existing slabs is supported here.`;
            break;
          }
          const summary = (draft.slabs || [])
            .slice()
            .sort((a, b) => a.slab.localeCompare(b.slab))
            .map(s => `${s.slab}: ${s.product} \u2192 ${s.gift}`)
            .join('\n');
          reply = `Updated Slab ${letter}.\n\n${summary}\n\n` +
            'Reply *CONFIRM* if this all looks right now, or fix another slab the same way.';
        }
      }
    }
    break;
  }

  // ----------------------------------------------------------------
  // 2. Locations -- one message, comma or newline separated.
  // ----------------------------------------------------------------
  case 'awaiting_locations': {
    const locations = splitList(text);
    if (locations.length === 0) {
      reply = 'Please send at least one pickup location.';
    } else {
      draft.locations = locations;
      draft.price_index = 0;
      newStatus = 'awaiting_price_entry';
      const firstSlab = (draft.slabs || [])[0];
      const letter = firstSlab ? firstSlab.slab : 'A';
      reply = `Got it \u2014 ${locations.join(', ')}.\n\n` +
        `Now, what's Slab ${letter}'s price (${firstSlab ? firstSlab.product : ''})?\n` +
        `Reply with one number if it's the same at every location, or ${locations.length} numbers in this order: ${locations.join(', ')}.\n` +
        `e.g. "37000" or "37000, 37000, 38000"`;
    }
    break;
  }

  // ----------------------------------------------------------------
  // 3. Per-slab pricing across all locations. Loops through however
  //    many slabs actually exist for this cycle, whether they came
  //    from table_4 text loop above or a flyer.
  // ----------------------------------------------------------------
  case 'awaiting_price_entry': {
    const idx = draft.price_index || 0;
    const slabs = draft.slabs || [];
    const currentSlab = slabs[idx];
    const locations = draft.locations || [];
    const prices = parsePrices(text, locations);
    if (!prices) {
      reply = `Please send either 1 price (same everywhere) or ${locations.length} prices, one per location in this order: ${locations.join(', ')}.`;
    } else if (!currentSlab) {
      reply = 'Something went wrong tracking which slab this price is for. Please start again with /newpromo.';
      newStatus = 'complete';
    } else {
      currentSlab.prices = prices;
      draft.price_index = idx + 1;
      if (draft.price_index < slabs.length) {
        const nextSlab = slabs[draft.price_index];
        newStatus = 'awaiting_price_entry';
        reply = `Slab ${currentSlab.slab} priced \u2014 ${pricesLine(prices)}.\n\n` +
          `Now Slab ${nextSlab.slab}'s price (${nextSlab.product})? Same format as before.`;
      } else {
        draft.name = 'MaketNG Promo'; // change later via /editpromo "name: ..." if needed
        newStatus = 'awaiting_collection_date';
        reply = `Slab ${currentSlab.slab} priced \u2014 ${pricesLine(prices)}.\n\n` +
          `All pricing is in. Lastly \u2014 what date can customers collect their gifts? ` +
          `(the day after you plan to close the promo, or whatever works for you)\ne.g. "4 August 2026", or send "skip" if you don't know yet \u2014 you can add it later with /editpromo.`;
      }
    }
    break;
  }

  case 'awaiting_collection_date': {
    if (/^skip$/i.test(text)) {
      draft.collection_date = null;
      newStatus = 'awaiting_confirm';
      reply = 'No problem, left blank for now.\n\n' + buildConfirmReply(draft);
    } else {
      const collect = new Date(text);
      if (isNaN(collect)) {
        reply = 'Sorry, I couldn\'t read that date. Try a format like "4 August 2026", or send "skip".';
      } else {
        draft.collection_date = collect.toISOString().split('T')[0];
        newStatus = 'awaiting_confirm';
        reply = buildConfirmReply(draft);
      }
    }
    break;
  }
  case 'awaiting_confirm': {
    if (/^confirm$/i.test(text)) {
      newStatus = 'ready_to_save';
    } else if (/^cancel$/i.test(text)) {
      newStatus = 'complete';
      reply = 'Cancelled \u2014 no changes made.';
    } else {
      reply = 'Please reply *CONFIRM* to save this promo cycle, or *CANCEL* to discard it.';
    }
    break;
  }
  case 'editing': {
    if (/^done$/i.test(text)) {
      newStatus = 'complete';
      reply = 'All set \u2014 changes saved. Type /editpromo again anytime to make more changes.';
    } else {
      const m = text.match(/^(name|collection date|slab [a-j])\s*:\s*(.+)$/i);
      if (!m) {
        reply = 'Please use the format "field: value".\nFields: name, collection date, slab <letter>.\n' +
          '(To change when the promo runs, use /startpromo or /stoppromo instead \u2014 not editable here. ' +
          'The number of slabs is also fixed once a promo is created \u2014 only editing existing ones is supported.)\n' +
          'For a slab: "slab a: product, gift, price[, price...]" (one price per location, or one price for all).\n' +
          'Send "done" when finished.';
      } else {
        const field = m[1].toLowerCase();
        const value = m[2].trim();
        let ok = true;
        let edit = { name: null, starts_at: null, ends_at: null, collection_date: null, slab_letter: null, slab_json: null };

        if (field === 'name') {
          edit.name = value;
        } else if (field === 'collection date') {
          const c = new Date(value);
          if (isNaN(c)) { ok = false; reply = 'Couldn\'t read that date.'; }
          else { edit.collection_date = c.toISOString().split('T')[0]; }
        } else {
          const letter = field.slice(-1).toUpperCase();
          const parts = value.split(',').map(s => s.trim());
          const editLocations = draft.locations || [];
          if (parts.length < 3) {
            ok = false;
            reply = `Send as "product, gift, price[, price...]" \u2014 one price per location (${editLocations.join(', ') || 'locations not on file'}), or one price for all.`;
          } else {
            const [product, gift, ...priceParts] = parts;
            const prices = parsePrices(priceParts.join(','), editLocations);
            if (!prices) {
              ok = false;
              reply = `Please send either 1 price or ${editLocations.length} prices (one per location: ${editLocations.join(', ')}).`;
            } else {
              edit.slab_letter = letter;
              edit.slab_json = JSON.stringify({ slab: letter, product, gift, prices });
            }
          }
        }

        if (ok) {
          pendingEdit = edit;
          reply = `Updated ${field}. Send another edit, or "done" to finish.`;
        }
        newStatus = 'editing';
      }
    }
    break;
  }
  default: {
    newStatus = 'complete';
    reply = 'Something went wrong with the promo setup. Please start again with /newpromo.';
  }
}

return [{ json: {
  session_id: session.id,
  new_status: newStatus,
  draft,
  reply,
  chat_id: chatId,
  target_cycle_id: draft.target_cycle_id || null,
  pending_edit: pendingEdit,
  has_pending_edit: !!pendingEdit
} }];

const cycle = $('Get Cycle To Edit').first().json;
const slabs = (cycle.slabs || []).slice().sort((a, b) => a.slab.localeCompare(b.slab));

function fmt(d) {
  if (!d) return 'not set yet';
  return new Date(d).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
}

function pricesLine(prices) {
  return Object.entries(prices || {}).map(([loc, p]) => `${loc}: \u20a6${p.toLocaleString()}`).join(', ');
}

let status;
if (!cycle.starts_at) status = 'Not started yet';
else if (!cycle.ends_at) status = `Active since ${fmt(cycle.starts_at)}`;
else status = `Closed on ${fmt(cycle.ends_at)}`;

const slabLines = slabs.map(s =>
  `${s.slab}: ${s.product} \u2192 ${s.gift}\n   ${pricesLine(s.prices)}`
).join('\n');

const slabLetters = slabs.map(s => s.slab).join(', ');
const exampleLetter = slabs.length > 0 ? slabs[0].slab.toLowerCase() : 'a';

const reply = `Editing *${cycle.name}*:\n\n` +
  `Status: ${status}\n` +
  `Collection: ${fmt(cycle.collection_date)}\n` +
  `Locations: ${(cycle.locations || []).join(', ')}\n\n${slabLines}\n\n` +
  'Send edits as "field: value":\n' +
  '\u2022 name: ...\n' +
  '\u2022 collection date: ...\n' +
  `\u2022 slab ${exampleLetter}: product, gift, price[, price...] (one per location, or one for all)\n` +
  `(this promo has ${slabs.length} slab${slabs.length === 1 ? '' : 's'}: ${slabLetters} \u2014 the count is fixed, only editing existing ones is supported)\n\n` +
  '(Use /startpromo or /stoppromo to change when the promo runs.)\n\n' +
  'Send "done" when finished.';

return [{ json: { reply } }];

const session = $('Get Admin Session').first().json;
const msg = $('Telegram Trigger').first().json.message || {};
const text = (msg.text || '').trim();
const chatId = msg.chat?.id;

let reply = '';
let passwordToSet = '';
const pendingPayment = (session.draft && session.draft.pending_payment) || null;

if (text.length < 6) {
  reply = 'That\'s too short \u2014 please choose a password with at least 6 characters.';
} else {
  passwordToSet = text;
}

return [{ json: {
  session_id: session.id,
  reply,
  chat_id: chatId,
  password_to_set: passwordToSet,
  pending_payment: pendingPayment
} }];

let paymentDetails = null;
let chatId = null;

try {
  const j = $('Route Admin Message').first().json;
  if (j && j.route === 'set_payment_request') {
    paymentDetails = j.payment_details;
    chatId = j.chat_id;
  }
} catch (e) {}

if (!paymentDetails) {
  try {
    const j = $('Continue Payment Setup').first().json;
    if (j && j.pending_payment) {
      paymentDetails = j.pending_payment;
      chatId = j.chat_id;
    }
  } catch (e) {}
}

return [{ json: { payment_details: paymentDetails, chat_id: chatId } }];

