  const base64 = $json.base64;
  const mimeType = $json.mimeType;

  const prompt = 'You are reading a promotional flyer for a retail "buy 1 carton, get free gift bars" trade promotion. ' +
    'It can show anywhere from 1 to 10 product slabs, usually labeled with letters starting at A (A, B, C, D, and so on). ' +
    'For each slab actually shown on the flyer, extract only: the product name and the free gift description (e.g. "18 bars of X"). ' +
    'Only include slabs that are genuinely present in the image -- do not invent slabs that are not shown. ' +
    'Do NOT extract prices or dates -- pricing is collected separately and may differ from table_43 shown on the flyer. ' +
    'Respond with ONLY a raw JSON array, nothing else, no markdown, no explanation, in this exact shape: ' +
    '[{"slab":"A","product":"...","gift":"..."}]';

  return {
    model: 'qwen/qwen3.6-27b',
    messages: [{
      role: 'user',
      content: [
        { type: 'text', text: prompt },
        { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64}` } }
      ]
    }],
    max_tokens: 1024,
    temperature: 0.1
  };
})() }}

parameters.jsCode:
const session = $('Get Admin Session').first().json;
let draft = session.draft || {};

const raw = $input.first().json.choices?.[0]?.message?.content || '';
let slabs = null;
let reply = '';
let newStatus = session.status;

try {
  const jsonMatch = raw.match(/\[[\s\S]*\]/);
  const parsed = JSON.parse(jsonMatch ? jsonMatch[0] : raw);
  if (Array.isArray(parsed) && parsed.length > 0) {
    slabs = parsed
      .filter(s => s.slab && s.product && s.gift)
      .slice(0, 10) // MAX_SLABS -- ignore anything beyond 10 even if the flyer somehow has more
      .map((s, i) => ({
        slab: String.fromCharCode(65 + i), // re-letter sequentially A, B, C... regardless of what the flyer/model labeled them
        product: s.product,
        gift: s.gift,
        prices: {}
      }));
  }
} catch (e) {
  slabs = null;
}

if (!slabs || slabs.length === 0) {
  reply = 'Sorry, I couldn\'t read the flyer clearly. Could you try a clearer photo, or type the slab details instead?\n\nSlab A \u2014 send: product, gift';
} else {
  draft.slabs = slabs;
  newStatus = 'awaiting_flyer_confirm';
  const summary = slabs.map(s => `${s.slab}: ${s.product} \u2192 ${s.gift}`).join('\n');
  reply = `Got it \u2014 here's what I read from table_4 flyer:\n\n${summary}\n\n` +
    'Please double-check this \u2014 vision models can misread flyers. If it all looks right, reply *CONFIRM* to continue.\n\n' +
    'To fix any slab, send it like: "slab a: correct product, correct gift" (one at a time, however many need fixing).';
}

return [{ json: {
  session_id: session.id,
  new_status: newStatus,
  draft,
  reply,
  chat_id: $('Telegram Trigger').first().json.message.chat?.id,
  target_cycle_id: draft.target_cycle_id || null,
  pending_edit: null,
  has_pending_edit: false
} }];

const item = $input.first();
const binaryPropertyName = Object.keys(item.binary || {})[0];

if (!binaryPropertyName) {
  throw new Error('No binary data found on the downloaded flyer file.');
}

const buffer = await this.helpers.getBinaryDataBuffer(0, binaryPropertyName);
const base64 = buffer.toString('base64');
const mimeType = item.binary[binaryPropertyName].mimeType || 'image/jpeg';

return [{ json: { base64, mimeType } }];

const info = $input.first().json;

function fmt(d) {
  if (!d) return 'unknown date';
  return new Date(d).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
}

let promoLine;
if (info.active_cycle) {
  promoLine = `\ud83d\udfe2 *${info.active_cycle.name}* is live (started ${fmt(info.active_cycle.starts_at)})`;
} else if (info.pending_cycle) {
  promoLine = `\ud83d\udfe1 *${info.pending_cycle.name}* is created but NOT live \u2014 send /startpromo to activate it`;
} else if (info.last_closed_cycle) {
  promoLine = `\u26aa No promo running. Last one, *${info.last_closed_cycle.name}*, was closed ${fmt(info.last_closed_cycle.ends_at)}. Use /newpromo to set up the next one.`;
} else {
  promoLine = '\u26aa No promo cycle has ever been created. Use /newpromo to set one up.';
}

const paymentLine = info.payment_set
  ? '\u2705 Payment details are set'
  : '\u26a0\ufe0f Payment details are NOT set \u2014 use /setpayment';

// Readable labels for each step, grouped by which flow they belong to.
const NEW_PROMO_STEPS = {
  awaiting_slab_a: 'entering Slab A', awaiting_slab_b: 'entering Slab B', awaiting_slab_c: 'entering Slab C',
  awaiting_flyer_confirm: 'confirming the flyer-read slabs', awaiting_locations: 'entering pickup locations',
  awaiting_price_a: 'pricing Slab A', awaiting_price_b: 'pricing Slab B', awaiting_price_c: 'pricing Slab C',
  awaiting_collection_date: 'setting the gift collection date', awaiting_confirm: 'final review, waiting on CONFIRM/CANCEL'
};

let wizardLine = '';
if (info.wizard_status === 'editing') {
  wizardLine = '\n\n\u270f\ufe0f You have an *unfinished /editpromo* in progress. Reply "done" to close it out, or keep sending edits.';
} else if (info.wizard_status === '[ID]') {
  wizardLine = '\n\n\ud83d\udd10 You\'re mid-way through *setting up your security password* (first-time /setpayment). Reply with the password to finish.';
} else if (NEW_PROMO_STEPS[info.wizard_status]) {
  wizardLine = `\n\n\u26a0\ufe0f *Incomplete promo setup in progress* \u2014 you started /newpromo but haven't finished it ` +
    `(currently: ${NEW_PROMO_STEPS[info.wizard_status]}). ` +
    `This won't show up as "pending" above until you finish and CONFIRM it \u2014 reply to continue where you left off.`;
} else if (info.wizard_status) {
  wizardLine = `\n\n\ud83d\udcdd You're mid-way through a setup flow (status: ${info.wizard_status}). Reply to continue it.`;
}

const reply = `\ud83d\udcca *Status*\n\n${promoLine}\n${paymentLine}${wizardLine}`;

return [{ json: { reply } }];
